-- Ảnh thật cho 15 quán và 99 món (nguồn: bảng link ảnh của nhóm, đã tải về, đổi sang JPEG ≤ 480px).
-- DB mới: Docker tự chạy file này sau 01_schema.sql và 02_seed.sql.
-- DB đã có sẵn: chạy tay (chạy lại nhiều lần cũng được, ảnh cũ của các món/quán này được thay):
--   docker compose exec -T mysql mysql -ugoride -pgoride123 --default-character-set=utf8mb4 goride < database/03_images.sql
-- Ghép theo TÊN quán + TÊN món nên không phụ thuộc id trên từng máy.
SET NAMES utf8mb4;

-- Cơm Tấm Ba Ghiền · Cơm sườn bì chả
DELETE i FROM images i JOIN menu_items m ON m.image_id=i.id JOIN restaurants r ON m.restaurant_id = r.id AND r.name='Cơm Tấm Ba Ghiền' AND m.name='Cơm sườn bì chả';
INSERT INTO images(mime, bytes) VALUES ('image/jpeg', );
UPDATE menu_items m JOIN restaurants r ON m.restaurant_id = r.id AND r.name='Cơm Tấm Ba Ghiền' AND m.name='Cơm sườn bì chả' SET m.image_id = LAST_INSERT_ID();

